# En JavaScript (polling)
async function waitForJob(jobId) {
  while (true) {
    const response = await fetch(`/api/jobs/${jobId}`);
    const job = await response.json();

    if (job.status === 'completed') {
      return job.result;
    }

    await new Promise(resolve => setTimeout(resolve, 1000));
  }
}

