# En JavaScript
fetch('/api/data', {
  headers: {
    'If-None-Match': localStorage.getItem('data-etag')
  }
})
.then(response => {
  if (response.status === 304) {
    console.log('Utilise le cache ! 🚀');
    return JSON.parse(localStorage.getItem('data'));
  } else {
    // Nouveau contenu, mettre à jour le cache
    localStorage.setItem('data-etag', response.headers.get('ETag'));
    return response.json();
  }
});

