# En JavaScript - Gestion avec retry
class APIClient {
  async request(url, options = {}) {
    const response = await fetch(url, options);

    if (response.status === 503) {
      const retryAfter = response.headers.get('Retry-After');

      if (retryAfter) {
        const seconds = parseInt(retryAfter);
        console.log(`Service unavailable, retrying in ${seconds}s`);

        // Attendre et réessayer automatiquement
        await this.delay(seconds * 1000);
        return this.request(url, options);
      }

      throw new Error('Service temporarily unavailable');
    }

    return response;
  }

  delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

# Mode maintenance (middleware)
function maintenanceMode(req, res, next) {
  if (process.env.MAINTENANCE_MODE === 'true') {
    return res.status(503).json({
      error: 'Service unavailable',
      message: 'Scheduled maintenance in progress',
      maintenance_until: process.env.MAINTENANCE_UNTIL,
      retry_after: 1800 // 30 minutes
    });
  }
  next();
}

