# En JavaScript - Timeout côté client
function fetchWithTimeout(url, options = {}, timeout = 30000) {
  return Promise.race([
    fetch(url, options),
    new Promise((_, reject) => 
      setTimeout(() => reject(new Error('Request timeout')), timeout)
    )
  ]);
}

# Utilisation avec gestion d'erreur
async function apiCall(url) {
  try {
    const response = await fetchWithTimeout(url, {}, 30000);

    if (response.status === 504) {
      // Proposer alternative ou retry
      const shouldRetry = confirm('La requête a pris trop de temps. Réessayer ?');
      if (shouldRetry) {
        return apiCall(url); // Retry
      }
      throw new Error('Request timed out');
    }

    return response.json();
  } catch (error) {
    if (error.message === 'Request timeout') {
      showErrorMessage('La requête prend trop de temps. Essayez plus tard.');
    }
    throw error;
  }
}

# 504 vs autres timeouts
